local ScriptName = ...

local BANNED_PLAYERS = {
    "darwinmadrid",
}

local IGNORED_PLAYERS = {
    "Lang",
}

local BAN_MESSAGE = "iDepHub\n\nHas sido baneado de este script"

local Players     = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

local function makeMatcher(list)
    local set = {}
    for _, entry in ipairs(list) do
        local key = tostring(entry):lower()
        if key ~= "" then set[key] = true end
    end

    local cache = setmetatable({}, { __mode = "k" })

    return function(player)
        if not player then return false end
        local cached = cache[player]
        if cached ~= nil then return cached end
        local found = set[player.Name:lower()] == true or set[tostring(player.UserId)] == true
        cache[player] = found
        return found
    end
end

local isBanned  = makeMatcher(BANNED_PLAYERS)
local isIgnored = makeMatcher(IGNORED_PLAYERS)

if isBanned(LocalPlayer) then
    LocalPlayer:Kick(BAN_MESSAGE)
    return nil
end

local lib = UI_LOADER()
if type(lib) ~= "table" then
    error("[iDepHub] La librería no devolvió una interfaz válida")
end

return {
    ScriptName = ScriptName,
    UI         = lib,
    isIgnored  = isIgnored,
    isBanned   = isBanned,
}

end)("renyshot")
